"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[90812],{36648:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>r,contentTitle:()=>o,default:()=>c,frontMatter:()=>i,metadata:()=>s,toc:()=>d});var a=n(31085),h=n(71184);const i={sidebar_position:2,slug:"/bible/Daniel/Daniel_2",title:"Daniel 2",hide_table_of_contents:!0},o="Daniel",s={id:"bible/Daniel/Daniel 2",title:"Daniel 2",description:"Chapter 2",source:"@site/docs/bible/Daniel/Daniel 2.md",sourceDirName:"bible/Daniel",slug:"/bible/Daniel/Daniel_2",permalink:"/docs/bible/Daniel/Daniel_2",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/docs/bible/Daniel/Daniel 2.md",tags:[],version:"current",sidebarPosition:2,frontMatter:{sidebar_position:2,slug:"/bible/Daniel/Daniel_2",title:"Daniel 2",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"Daniel 1",permalink:"/docs/bible/Daniel/Daniel_1"},next:{title:"Daniel 3",permalink:"/docs/bible/Daniel/Daniel_3"}},r={},d=[{value:"Chapter 2",id:"chapter-2",level:2}];function l(e){const t={admonition:"admonition",h1:"h1",h2:"h2",p:"p",...(0,h.R)(),...e.components},{BibleText:n}=t;return n||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.h1,{id:"daniel",children:"Daniel"}),"\n",(0,a.jsx)(t.h2,{id:"chapter-2",children:"Chapter 2"}),"\n",(0,a.jsx)(t.p,{children:"Daniel, by divine revelation, declares the dream of Nabuchodonosor, and the interpretation of it.  He is highly honoured by the king."}),"\n",(0,a.jsx)(n,{verse:1,children:"In the second year of the reign of Nabuchodonosor, Nabuchodonosor had a dream, and his spirit was terrified, and his dream went out of his mind."}),"\n",(0,a.jsx)(t.admonition,{type:"note",children:(0,a.jsx)(t.p,{children:"Note 1: The second year...Viz., from the death of his father Nabopolassar; for he had reigned before as partner with his father in the empire."})}),"\n",(0,a.jsx)(n,{verse:2,children:"Then the king commanded to call together the diviners and the wise men, and the magicians, and the Chaldeans: to declare to the king his dreams: so they came and stood before the king."}),"\n",(0,a.jsx)(t.admonition,{type:"note",children:(0,a.jsx)(t.p,{children:"Note 1: The Chaldeeans...That is, the astrologers, that pretended to divine by stars."})}),"\n",(0,a.jsx)(n,{verse:3,children:"And the king said to them: I saw a dream: and being troubled in mind I know not what I saw."}),"\n",(0,a.jsx)(n,{verse:4,children:"And the Chaldeans answered the king in Syriac: O king, live for ever: tell to thy servants thy dream, and we will declare the interpretation thereof."}),"\n",(0,a.jsx)(n,{verse:5,children:"And the king, answering, said to the Chaldeans: The thing is gone out of my mind: unless you tell me the dream, and the meaning thereof, you shall be put to death, and your houses shall be confiscated."}),"\n",(0,a.jsx)(n,{verse:6,children:"but if you tell the dream, and the meaning of it, you shall receive of me rewards, and gifts, and great honour: therefore, tell me the dream, and the interpretation thereof."}),"\n",(0,a.jsx)(n,{verse:7,children:"They answered again and said: Let the king tell his servants the dream, and we will declare the interpretation of it."}),"\n",(0,a.jsx)(n,{verse:8,children:"The king answered and said: I know for certain, that you seek to gain time, since you know that the thing is gone from me."}),"\n",(0,a.jsx)(n,{verse:9,children:"If, therefore, you tell me not the dream, there is one sentence concerning you, that you have also framed a lying interpretation, and full of deceit, to speak before me till the time pass away. Tell me, therefore, the dream, that I may know that you also give a true interpretation thereof."}),"\n",(0,a.jsx)(n,{verse:10,children:"Then the Chaldeans answered before the king, and said: There is no man upon earth, that can accomplish thy word, O king; neither doth any king, though great and mighty, ask such a thing of any diviner, or wise man, or Chaldean."}),"\n",(0,a.jsx)(n,{verse:11,children:"For the thing that thou asketh, O king, is difficult: nor can any one be found that can shew it before the king, except the gods, whose conversation is not with men."}),"\n",(0,a.jsx)(n,{verse:12,children:"Upon hearing this, the king in fury, and in great wrath, commanded that all the wise men of Babylon should be put to death."}),"\n",(0,a.jsx)(n,{verse:13,children:"And the decree being gone forth, the wise men were slain: and Daniel and his companions were sought for, to be put to death."}),"\n",(0,a.jsx)(n,{verse:14,children:"Then Daniel inquired concerning the law and the sentence, of Arioch, the general of the king's army, who was gone forth to kill the wise men of Babylon."}),"\n",(0,a.jsx)(n,{verse:15,children:"And he asked him that had received the orders of the king, why so cruel a sentence was gone forth from the face of the king. And when Arioch had told the matter to Daniel,"}),"\n",(0,a.jsx)(n,{verse:16,children:"Daniel went in, and desired of the king, that he would give him time to resolve the question, and declare it to the king."}),"\n",(0,a.jsx)(n,{verse:17,children:"And he went into his house, and told the matter to Ananias, and Misael, and Azarias, his companions:"}),"\n",(0,a.jsx)(n,{verse:18,children:"To the end that they should ask mercy at the face of the God of heaven, concerning this secret, and that Daniel and his companions might not perish with the rest of the wise men of Babylon."}),"\n",(0,a.jsx)(n,{verse:19,children:"Then was the mystery revealed to Daniel by a vision in the night: and Daniel blessed the God of heaven,"}),"\n",(0,a.jsx)(n,{verse:20,children:"And speaking, he said: Blessed be the name of the Lord from eternity and for evermore: for wisdom and fortitude are his."}),"\n",(0,a.jsx)(n,{verse:21,children:"And he changeth times and ages: taketh away kingdoms, and establisheth them: giveth wisdom to the wise, and knowledge to them that have understanding:"}),"\n",(0,a.jsx)(n,{verse:22,children:"He revealeth deep and hidden things, and knoweth what is in darkness: and light is with him."}),"\n",(0,a.jsx)(n,{verse:23,children:"To thee, O God of our fathers, I give thanks, and I praise thee: because thou hast given me wisdom and strength: and now thou hast shewn me what we desired of thee, for thou hast made known to us the king's discourse."}),"\n",(0,a.jsx)(n,{verse:24,children:"After this Daniel went in to Arioch, to whom the king had given orders to destroy the wise men of Babylon, and he spoke thus to him: Destroy not the wise men of Babylon: bring me in before the king, and I will tell the solution to the king."}),"\n",(0,a.jsx)(n,{verse:25,children:"Then Arioch in haste brought in Daniel to the king, and said to him: I have found a man of the children of the captivity of Juda, that will resolve the question to the king."}),"\n",(0,a.jsx)(n,{verse:26,children:"The king answered, and said to Daniel, whose name was Baltassar: Thinkest thou indeed that thou canst tell me the dream that I saw, and the interpretation thereof?"}),"\n",(0,a.jsx)(n,{verse:27,children:"And Daniel made answer before the king, and said: The secret that the king desireth to know, none of the wise men, or the philosophers, or the diviners, or the soothsayers, can declare to the king."}),"\n",(0,a.jsx)(n,{verse:28,children:"But there is a God in heaven that revealeth mysteries, who hath shewn to thee, O king Nabuchodonosor, what is to come to pass in the latter times. Thy dream, and the visions of thy head upon thy bed, are these:"}),"\n",(0,a.jsx)(n,{verse:29,children:"Thou, O king, didst begin to think in thy bed, what should come to pass hereafter: and he that revealeth mysteries shewed thee what shall come to pass."}),"\n",(0,a.jsx)(n,{verse:30,children:"To me also this secret is revealed, not by any wisdom that I have more than all men alive: but that the interpretation might be made manifest to the king, and thou mightest know the thought of thy mind."}),"\n",(0,a.jsx)(n,{verse:31,children:"Thou, O king, sawest, and behold there was as it were a great statue: this statue, which was great and high, tall of stature, stood before thee, and the look thereof was terrible."}),"\n",(0,a.jsx)(n,{verse:32,children:"The head of this statue was of fine gold, but the breast and the arms of silver, and the belly and the thighs of brass."}),"\n",(0,a.jsx)(n,{verse:33,children:"And the legs of iron, the feet part of iron and part of clay."}),"\n",(0,a.jsx)(n,{verse:34,children:"Thus thou sawest, till a stone was cut out of a mountain without hands: and it struck the statue upon the feet thereof that were of iron and clay, and broke them in pieces."}),"\n",(0,a.jsx)(n,{verse:35,children:"Then was the iron, the clay, the brass, the silver, and the gold broken to pieces together, and became like the chaff of a summer's threshing floor, and they were carried away by the wind: and there was no place found for them: but the stone that struck the statue became a great mountain, and filled the whole earth."}),"\n",(0,a.jsx)(n,{verse:36,children:"This is the dream: we will also tell the interpretation thereof before thee, O king."}),"\n",(0,a.jsx)(n,{verse:37,children:"Thou art a king of kings: and the God of heaven hath given thee a kingdom, and strength, and power, and glory:"}),"\n",(0,a.jsx)(n,{verse:38,children:"And all places wherein the children of men, and the beasts of the field do dwell: he hath also given the birds of the air into thy hand, and hath put all things under thy power: thou, therefore, art the head of gold."}),"\n",(0,a.jsx)(n,{verse:39,children:"And after thee shall rise up another kingdom, inferior to thee, of silver: and another third kingdom of brass, which shall rule over all the world."}),"\n",(0,a.jsx)(t.admonition,{type:"note",children:(0,a.jsx)(t.p,{children:"Note 1: Another kingdom...Viz., that of the Medes and Persians. Ibid. Third\nNote 2: kingdom...Viz., that of Alexander the Great."})}),"\n",(0,a.jsx)(n,{verse:40,children:"And the fourth kingdom shall be as iron. As iron breaketh into pieces, and subdueth all things, so shall that break, and destroy all these."}),"\n",(0,a.jsx)(t.admonition,{type:"note",children:(0,a.jsx)(t.p,{children:"Note 1: The fourth kingdom, etc...Some understand this of the successors of Alexander, the kings of Syria and Egypt, others of the Roman empire, and its civil wars."})}),"\n",(0,a.jsx)(n,{verse:41,children:"And whereas thou sawest the feet, and the toes, part of potter's clay, and part of iron: the kingdom shall be divided, but yet it shall take its origin from the iron, according as thou sawest the iron mixed with the miry clay."}),"\n",(0,a.jsx)(n,{verse:42,children:"And as the toes of the feet were part of iron, and part of clay: the kingdom shall be partly strong, and partly broken."}),"\n",(0,a.jsx)(n,{verse:43,children:"And whereas thou sawest the iron mixed with miry clay, they shall be mingled indeed together with the seed of man, but they shall not stick fast one to another, as iron cannot be mixed with clay."}),"\n",(0,a.jsx)(n,{verse:44,children:"But in the days of those kingdoms, the God of heaven will set up a kingdom that shall never by destroyed, and his kingdom shall not be delivered up to another people: and it shall break in pieces, and shall consume all these kingdoms: and itself shall stand for ever."}),"\n",(0,a.jsx)(t.admonition,{type:"note",children:(0,a.jsx)(t.p,{children:"Note 1: A kingdom...Viz., the kingdom of Christ in the Catholic Church which cannot be destroyed."})}),"\n",(0,a.jsx)(n,{verse:45,children:"According as thou sawest, that the stone was cut out of the mountain without hands, and broke in pieces the clay and the iron, and the brass, and the silver, and the gold, the great God hath shewn the king what shall come to pass hereafter, and the dream is true, and the interpretation thereof is faithful."}),"\n",(0,a.jsx)(n,{verse:46,children:"Then king Nabuchodonosor fell on his face, and worshipped Daniel, and commanded that they should offer in sacrifice to him victims and incense."}),"\n",(0,a.jsx)(n,{verse:47,children:"And the king spoke to Daniel, and said: Verily, your God is the God of gods, and Lord of kings, and a revealer of hidden things: seeing thou couldst discover this secret."}),"\n",(0,a.jsx)(n,{verse:48,children:"Then the king advanced Daniel to a high station, and gave him many and great gifts: and he made him governor over all the provinces of Babylon: and chief of the magistrates over all the wise men of Babylon."}),"\n",(0,a.jsx)(n,{verse:49,children:"And Daniel requested of the king, and he appointed Sidrach, Misach, and Abdenago, over the works of the province of Babylon: but Daniel himself was in the king's palace."})]})}function c(e={}){const{wrapper:t}={...(0,h.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(l,{...e})}):l(e)}},71184:(e,t,n)=>{n.d(t,{R:()=>o,x:()=>s});var a=n(14041);const h={},i=a.createContext(h);function o(e){const t=a.useContext(i);return a.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(h):e.components||h:o(e.components),a.createElement(i.Provider,{value:t},e.children)}}}]);